<script>
(function () {
  var cards = Array.prototype.slice.call(document.querySelectorAll(".card"));
  var filterButtons = Array.prototype.slice.call(document.querySelectorAll("[data-filter]"));
  var status = document.getElementById("status");

  var filterNames = { all: "all plants", sun: "plants that love sun", shade: "plants that like shade" };

  function applyFilter(filter) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = filter === "all" || card.dataset.light === filter;
      card.hidden = !match;
      if (match) shown++;
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute("aria-pressed", String(btn.dataset.filter === filter));
    });
    status.textContent = "Showing " + shown + " of " + cards.length + " plants (" + filterNames[filter] + ").";
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      applyFilter(btn.dataset.filter);
    });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector(".plant-btn");
    btn.addEventListener("click", function () {
      var planted = btn.dataset.planted !== "true";
      btn.dataset.planted = String(planted);
      card.dataset.planted = String(planted);
      btn.textContent = planted ? "Planted" : "Mark as planted";
      status.textContent = card.dataset.name + (planted ? " marked as planted." : " is no longer marked as planted.");
    });
  });

  applyFilter("all");
})();
